    {
        Assert.Equal(4_750, _useCase.For(5_000, LoyaltyTier.Gold));
    }

    [Fact]
    public void Gold_member_pays_nothing_for_an_empty_basket()
    {
        Assert.Equal(0, _useCase.For(0, LoyaltyTier.Gold));
    }
}
